"""Exact helper logic reused from reviewed runtime_probe.py; fixture assembly only."""
import sqlite3
def hydrate(x,path):
  db=sqlite3.connect(path);db.executescript('CREATE TABLE head(id INTEGER PRIMARY KEY,raw BLOB);CREATE TABLE events(seq INTEGER PRIMARY KEY,raw BLOB);CREATE TABLE blobs(ref TEXT PRIMARY KEY,raw BLOB);CREATE TABLE journal(challenge TEXT PRIMARY KEY,request BLOB,response BLOB);')
  db.execute('INSERT INTO head VALUES(1,?)',(bytes.fromhex(x['head']),));db.executemany('INSERT INTO events VALUES(?,?)',[(n,bytes.fromhex(b)) for n,b in x['events']]);db.executemany('INSERT INTO blobs VALUES(?,?)',[(n,bytes.fromhex(b)) for n,b in x['blobs']]);db.executemany('INSERT INTO journal VALUES(?,?,?)',[(n,bytes.fromhex(b),None if c is None else bytes.fromhex(c)) for n,b,c in x['journal']]);db.commit();db.close()
  own=path.with_suffix('.owners');db=sqlite3.connect(own);db.executescript('CREATE TABLE meta(id INTEGER PRIMARY KEY,raw BLOB);CREATE TABLE coordinates(coord TEXT PRIMARY KEY,raw BLOB,hash TEXT);');db.execute('INSERT INTO meta VALUES(1,?)',(bytes.fromhex(x['ownership_meta']),));db.executemany('INSERT INTO coordinates VALUES(?,?,?)',[(n,bytes.fromhex(b),h) for n,b,h in x['owners']]);db.commit();db.close();return own
def export(auth,x):
  db=auth.db;return dict(x,expected_head=auth.state()['head'],head=db.execute('select raw from head').fetchone()[0].hex(),events=[[n,b.hex()] for n,b in db.execute('select seq,raw from events order by seq')],blobs=[[n,b.hex()] for n,b in db.execute('select ref,raw from blobs order by ref')],journal=[[n,b.hex(),None if r is None else r.hex()] for n,b,r in db.execute('select challenge,request,response from journal order by challenge')],owners=[[n,b.hex(),h] for n,b,h in db.execute('select coord,raw,hash from ownership.coordinates order by coord')])
